const msg = $json.message || $json;

const chatId = msg.chat?.id;
const userId = msg.from?.id;
const username = msg.from?.username || msg.from?.first_name || "telegram_user";
const text = (msg.text || "").trim();

let command = "";
let argument = "";

if (text.startsWith("/")) {
  const firstSpaceIndex = text.indexOf(" ");
  if (firstSpaceIndex === -1) {
    command = text.toLowerCase();
    argument = "";
  } else {
    command = text.substring(0, firstSpaceIndex).toLowerCase();
    argument = text.substring(firstSpaceIndex + 1).trim();
  }
} else {
  command = "unknown";
  argument = text;
}

return [
  {
    json: {
      chat_id: chatId,
      user_id: userId,
      username,
      text,
      command,
      argument,
      backend_base_url: $json.backend_base_url
    }
  }
];

const data = $input.first().json;
const chatId = $('Parse Telegram Message').first().json.chat_id;

function nutritionToText(nutrition) {
  if (!nutrition || typeof nutrition !== "object") {
    return "Not available";
  }
  const entries = Object.entries(nutrition);
  if (entries.length === 0) {
    return "Not available";
  }
  return entries.map(([key, value]) => `${key}: ${value}`).join("\n");
}

let message = "";

if (data.error) {
  message =
`⚠️ Service Temporarily Unavailable

I could not reach the backend right now.
Please check whether the backend service is running.`;
} else if (data.status === "FOUND") {
  const product = data.product || (data.products && data.products[0]);

  if (product) {
    message =
`📦 Product Found

Name: ${product.name || "Not available"}
Brand: ${product.brand || "Not available"}
Category: ${product.category || "Not available"}
SKU: ${product.sku || "Not available"}
Barcode: ${product.barcode || "Not available"}

Ingredients:
${product.ingredients || "Not available"}

Nutrition:
${nutritionToText(product.nutrition_info)}

Storage:
${product.storage_instruction || "Not available"}

Source:
${data.source || "Not available"}`;
  } else if (data.products && data.products.length > 0) {
    message = "📦 Products Found\n\n" + data.products.map((p, index) => {
      return `${index + 1}. ${p.name || "Unknown Product"}
Brand: ${p.brand || "Not available"}
Category: ${p.category || "Not available"}
Barcode: ${p.barcode || "Not available"}`;
    }).join("\n\n");
  } else {
    message = "Product found, but response format was unexpected.";
  }
} else if (data.status === "NOT_FOUND") {
  message =
`❌ Product Not Found

Query: ${data.query || "Not available"}

${data.message || "Product was not found."}

Suggested Action:
${data.suggested_action || "Create a new product master record."}`;
} else if (data.status === "INVALID_QUERY") {
  message =
`⚠️ Invalid Product Query

${data.message || "Please provide a barcode, product name, product ID, or SKU."}`;
} else {
  message =
`⚠️ Product Lookup Failed

Status: ${data.status || "Unknown"}
Message: ${data.message || "Unexpected response from backend."}`;
}

return [
  {
    json: {
      chat_id: chatId,
      message
    }
  }
];

const data = $input.first().json;
const chatId = $('Parse Telegram Message').first().json.chat_id;
let message = "";

function escapeMarkdown(text) {
  if (!text) return text;
  return String(text).replace(/([_*\[\]()~`>#+=|{}.!\-])/g, "\\$1");
}

if (data.error) {
  message =
`⚠️ Service Temporarily Unavailable

I could not reach the backend right now.
Please check whether the backend service is running.`;
} else if (data.status === "ANSWERED") {
  const d = data.data || {};

  if (data.intent === "EXPIRY_DATE") {
    message =
`📅 Expiry Date

Product: ${escapeMarkdown(d.product_name) || "Not available"}
Barcode: ${escapeMarkdown(d.barcode) || "Not available"}
Batch: ${escapeMarkdown(d.batch_number) || "Not available"}
Expiry Date: ${escapeMarkdown(d.expiry_date) || "Not available"}
Status: ${escapeMarkdown(d.pipeline_status) || "Not available"}`;
  } else if (data.intent === "MFG_DATE") {
    message =
`🏭 Manufacturing Date

Product: ${escapeMarkdown(d.product_name) || "Not available"}
Batch: ${escapeMarkdown(d.batch_number) || "Not available"}
MFG Date: ${escapeMarkdown(d.manufacturing_date) || "Not available"}
Status: ${escapeMarkdown(d.pipeline_status) || "Not available"}`;
  } else if (data.intent === "BATCH_NUMBER") {
    message =
`🔢 Batch Number

Product: ${escapeMarkdown(d.product_name) || "Not available"}
Batch: ${escapeMarkdown(d.batch_number) || "Not available"}
MFG Date: ${escapeMarkdown(d.manufacturing_date) || "Not available"}
Expiry Date: ${escapeMarkdown(d.expiry_date) || "Not available"}`;
  } else if (data.intent === "INGREDIENTS") {
    message =
`🥣 Ingredients

Product: ${escapeMarkdown(d.product_name) || "Not available"}

${escapeMarkdown(d.ingredients) || "Ingredients not available"}`;
  } else if (data.intent === "NUTRITION") {
    const nutrition = d.nutrition_info || {};
    const nutritionText = Object.keys(nutrition).length
      ? Object.entries(nutrition).map(([k, v]) => `${escapeMarkdown(k)}: ${escapeMarkdown(v)}`).join("\n")
      : "Nutrition information not available";

    message =
`🍽️ Nutrition Information

Product: ${escapeMarkdown(d.product_name) || "Not available"}

${nutritionText}`;
  } else if (data.intent === "STORAGE_INSTRUCTION") {
    message =
`🧊 Storage Instruction

Product: ${escapeMarkdown(d.product_name) || "Not available"}

${escapeMarkdown(d.storage_instruction) || "Storage instruction not available"}`;
  } else if (data.intent === "PRODUCT_STATUS") {
    message =
`✅ Product Status

Product: ${escapeMarkdown(d.product_name) || "Not available"}
Batch: ${escapeMarkdown(d.batch_number) || "Not available"}
Expiry Date: ${escapeMarkdown(d.expiry_date) || "Not available"}
Status: ${escapeMarkdown(d.status) || "Not available"}
Pipeline Status: ${escapeMarkdown(d.pipeline_status) || "Not available"}`;
  } else if (data.intent === "PRODUCT_DETAILS") {
    const p = d.product || {};
    message =
`📦 Product Details

Name: ${escapeMarkdown(p.name) || "Not available"}
Brand: ${escapeMarkdown(p.brand) || "Not available"}
Category: ${escapeMarkdown(p.category) || "Not available"}
SKU: ${escapeMarkdown(p.sku) || "Not available"}
Barcode: ${escapeMarkdown(p.barcode) || "Not available"}

Description:
${escapeMarkdown(p.description) || "Not available"}

Storage:
${escapeMarkdown(p.storage_instruction) || "Not available"}`;
  } else {
    message = escapeMarkdown(data.answer) || "Answer found.";
  }
} else if (data.status === "NOT_FOUND") {
  message =
`❌ Not Found

${escapeMarkdown(data.answer) || "No matching product data was found."}`;
} else if (data.status === "UNSUPPORTED_INTENT") {
  message =
`⚠️ Unsupported Question

${escapeMarkdown(data.answer) || "I can only answer product-related database questions."}

Try:
/ask What is the expiry date of Amul Milk?
/ask Show ingredients of 8901262010011`;
} else if (data.status === "INVALID_QUESTION") {
  message =
`⚠️ Invalid Question

Please ask a product-related question.

Example:
/ask What is the expiry date of Amul Milk?`;
} else {
  message =
`⚠️ Question Failed

Status: ${escapeMarkdown(data.status) || "Unknown"}
Message: ${escapeMarkdown(data.answer) || "Unexpected response from backend."}`;
}

return [
  {
    json: {
      chat_id: chatId,
      message
    }
  }
];

const data = $input.first().json;
const chatId = $('Parse Telegram Message').first().json.chat_id;

let message = "";

if (data.error) {
  message =
`⚠️ Service Temporarily Unavailable

I could not reach the backend right now.
Please check whether the backend service is running.`;
} else if (data.status === "FOUND") {
  const products = data.products || [];
  if (products.length > 0) {
    message = `📂 Category: ${data.category || "Not available"}\n\n` + products.map((p, index) => {
      return `${index + 1}. ${p.name || "Unknown Product"}\nBrand: ${p.brand || "Not available"}\nSKU: ${p.sku || "Not available"}\nBarcode: ${p.barcode || "Not available"}`;
    }).join("\n\n") + `\n\nTotal: ${products.length} product(s)`;
  } else {
    message = "Category found, but no products were returned.";
  }
} else if (data.status === "NOT_FOUND") {
  message =
`❌ No Products Found

Category: ${data.category || data.query || "Not available"}

${data.message || "No products exist in this category."}`;
} else if (data.status === "INVALID_QUERY") {
  message =
`⚠️ Invalid Category

${data.message || "Please provide a valid category name."}`;
} else {
  message =
`⚠️ Category Lookup Failed

Status: ${data.status || "Unknown"}
Message: ${data.message || "Unexpected response from backend."}`;
}

return [
  {
    json: {
      chat_id: chatId,
      message
    }
  }
];

const raw = ($json.argument || "").trim();
const tokens = raw.split(/\s+/).filter(Boolean);

let confirmed = false;
let identifierTokens = tokens;

if (tokens.length > 0 && tokens[tokens.length - 1].toLowerCase() === "confirm") {
  confirmed = true;
  identifierTokens = tokens.slice(0, -1);
}

const identifier = identifierTokens.join(" ").trim();

return [
  {
    json: {
      ...$json,
      identifier,
      confirmed
    }
  }
];

const data = $input.first().json;
const chatId = $('Parse Telegram Message').first().json.chat_id;
let message = "";

if (data.error) {
  message =
`⚠️ Service Temporarily Unavailable

I could not reach the backend right now.
Please check whether the backend service is running.`;
} else if (data.status === "DELETED") {
  message =
`🗑️ Product Removed

${data.message || "The product record was successfully deleted."}`;
} else if (data.status === "NOT_FOUND") {
  message =
`❌ Product Not Found

${data.message || "No product matched the provided identifier. Nothing was deleted."}`;
} else if (data.status === "INVALID_QUERY") {
  message =
`⚠️ Invalid Identifier

${data.message || "Please provide a valid barcode, SKU, or product name."}`;
} else {
  message =
`⚠️ Removal Failed

Status: ${data.status || "Unknown"}
Message: ${data.message || "Unexpected response from backend."}`;
}

return [
  {
    json: {
      chat_id: chatId,
      message
    }
  }
];

const raw = ($json.argument || "").trim();
const tokens = raw.split(/\s+/).filter(Boolean);
const identifier = tokens[0] || "";
const fieldTokens = tokens.slice(1);

const updates = {};
const invalidTokens = [];

for (const t of fieldTokens) {
  const eqIndex = t.indexOf("=");
  if (eqIndex > 0) {
    const key = t.substring(0, eqIndex).trim();
    const value = t.substring(eqIndex + 1).trim();
    if (key) {
      updates[key] = value;
    }
  } else {
    invalidTokens.push(t);
  }
}

return [
  {
    json: {
      ...$json,
      identifier,
      updates,
      updateCount: Object.keys(updates).length,
      invalidTokens
    }
  }
];

const data = $input.first().json;
const chatId = $('Parse Telegram Message').first().json.chat_id;
let message = "";

function fieldsToText(fields) {
  if (!fields || typeof fields !== "object") return "Not available";
  const entries = Object.entries(fields);
  if (entries.length === 0) return "Not available";
  return entries.map(([k, v]) => `${k}: ${v}`).join("\n");
}

if (data.error) {
  message =
`⚠️ Service Temporarily Unavailable

I could not reach the backend right now.
Please check whether the backend service is running.`;
} else if (data.status === "UPDATED") {
  message =
`✅ Product Updated

${data.message || "The product record was successfully updated."}

Updated fields:
${fieldsToText(data.updated_fields || $('Parse Edit Command').first().json.updates)}`;
} else if (data.status === "NOT_FOUND") {
  message =
`❌ Product Not Found

${data.message || "No product matched the provided identifier. Nothing was updated."}`;
} else if (data.status === "INVALID_FIELD") {
  message =
`⚠️ Invalid Field

${data.message || "One or more fields provided are not editable."}`;
} else if (data.status === "INVALID_QUERY") {
  message =
`⚠️ Invalid Request

${data.message || "Please provide a valid identifier and field updates."}`;
} else {
  message =
`⚠️ Update Failed

Status: ${data.status || "Unknown"}
Message: ${data.message || "Unexpected response from backend."}`;
}

return [
  {
    json: {
      chat_id: chatId,
      message
    }
  }
];
